import { SimulationLegalReference, SimulationCaseVersion } from '../types/simulation';
import { SIMULATION_LEGAL_REFERENCES } from './practicalSimulationCases';

const getLessonLegalReferences = (...referenceIds: string[]): SimulationLegalReference[] =>
  referenceIds.map((referenceId) => {
    const reference = SIMULATION_LEGAL_REFERENCES.find((item) => item.id === referenceId);
    if (!reference) throw new Error(`Missing simulation legal reference: ${referenceId}`);
    return reference;
  });

export interface AnimatedLessonScene {
  id: string;
  title: string;
  narration: string;
  takeaway: string;
  subtitleCues?: string[];
  screenText?: string[];
}

export interface AnimatedKnowledgeCheckOption {
  id: string;
  label: string;
}

export interface AnimatedKnowledgeCheckQuestion {
  id: string;
  prompt: string;
  options: AnimatedKnowledgeCheckOption[];
  correctOptionId: string;
  explanation: string;
}

export interface AnimatedLesson {
  lessonId: string;
  title: string;
  description: string;
  category?: string;
  fictionalExample?: string;
  knowledgeCheck?: AnimatedKnowledgeCheckQuestion[];
  durationLabel: string;
  difficulty: string;
  videoPath: string;
  videoAvailable: boolean;
  posterPath: string;
  voiceOverPath: string;
  voiceOverAvailable: boolean;
  subtitlePath: string;
  transcriptPath: string;
  learningObjectives: string[];
  keyPoints: string[];
  linkedSimulationId: string;
  legalReferences: SimulationLegalReference[];
  contentReviewDate: string;
  publicationStatus: 'draft' | 'published';
  scenes: AnimatedLessonScene[];
}

const createNarratedScene = (
  id: string,
  title: string,
  subtitleCues: string[],
  takeaway: string,
  screenText: string[],
): AnimatedLessonScene => ({
  id,
  title,
  narration: subtitleCues.join(' '),
  subtitleCues,
  takeaway,
  screenText,
});

