export const getLessonForSimulation = (caseKey: string): AnimatedLesson | undefined =>
  ANIMATED_LESSONS.find((lesson) => lesson.linkedSimulationId === caseKey);

export const findLinkedSimulation = (
  lesson: AnimatedLesson,
  cases: SimulationCaseVersion[],
): SimulationCaseVersion | undefined =>
  cases.find((simulationCase) => simulationCase.caseKey === lesson.linkedSimulationId);
